    <div class="p-3 rounded border bg-light mb-4"><div class="d-flex justify-content-between align-items-center mb-2"><label class="fw-semibold text-primary mb-0"><i class="fas fa-clipboard-check me-1"></i>Alur Permohonan & Persyaratan Akses</label><div class="form-check"><input id="show-reqs" class="form-check-input" type="checkbox" checked><label class="form-check-label small" for="show-reqs">Tampilkan</label></div></div><input id="req-1" class="form-control form-control-sm mb-2" placeholder="Pengajuan akses oleh PIC department..."><input id="req-2" class="form-control form-control-sm" placeholder="Konfirmasi IT dan instruksi akses..."></div>
